const NUMBER='[-+]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][-+]?\\d+)?';
const PATTERNS=[
  [/^请重新选择当前评估中的(推荐供应商|备选供应商)。$/u,(_,field)=>`Choose the ${field==='推荐供应商'?'recommended':'alternative'} supplier from the current assessment again.`],
  [/^(推荐供应商|备选供应商)“([\s\S]*)”未满足准入要求，请更换供应商或清空选择。$/u,(_,field,name)=>`${field==='推荐供应商'?'Recommended':'Alternative'} supplier “${name}” does not meet eligibility requirements. Choose another supplier or clear the selection.`],
  [/^(推荐供应商|备选供应商)“([\s\S]*)”的准入信息待核验，请完成核验、更换供应商或清空选择。$/u,(_,field,name)=>`Eligibility for the ${field==='推荐供应商'?'recommended':'alternative'} supplier “${name}” is pending verification. Complete verification, choose another supplier or clear the selection.`],
  [/^指标「([\s\S]*)」的重要程度无效，请满足 0 < 最低值 ≤ 常用值 ≤ 最高值。$/u,(_,name)=>`Invalid importance for “${name}”. Use 0 < lower ≤ typical ≤ upper.`],
  [/^最多保存 (\d+) 个采购方案。$/u,(_,count)=>`Save up to ${count} procurement scenarios.`],
  [/^第 (\d+) 个方案的编号无效或重复。$/u,(_,index)=>`Scenario ${index} has an invalid or duplicate ID.`],
  [/^方案名称「([\s\S]*)」重复，请使用不同名称。$/u,(_,name)=>`Duplicate scenario name “${name}”. Use a unique name.`],
  [/^方案「([\s\S]*)」对应的供应商或指标已变化，请重新创建该方案。$/u,(_,name)=>`Suppliers or criteria have changed for “${name}”. Create the scenario again.`],
  [/^方案「([\s\S]*)」的指标数量与当前评估不一致。$/u,(_,name)=>`The criterion count in “${name}” does not match the current assessment.`],
  [/^方案「([\s\S]*)」含有未知或重复指标。$/u,(_,name)=>`Scenario “${name}” contains unknown or duplicate criteria.`],
  [/^已忽略 (\d+) 条损坏的本地记录，其余项目可继续使用。$/u,(_,count)=>`Ignored ${count} damaged local records. Other projects remain available.`],
  [/^(.*?) 的类型应为 cost 或 benefit。$/u,(_,name)=>`${name} must have type cost or benefit.`],
  [/^(.*?) (lower|modal|upper)必须是有限数值。$/u,(_,name,key)=>`${name} ${key} must be finite.`],
  [/^(.*?) 权重必须满足 0 < 下限 ≤ 众数 ≤ 上限。$/u,(_,name)=>`${name} weights must satisfy 0 < lower ≤ modal ≤ upper.`],
  [/^(.*?) 的评分数量与准则不一致。$/u,(_,name)=>`${name} has a different number of scores and criteria.`],
  [/^(.*?) 评分必须是有限数值。$/u,(_,name)=>`${name} score must be finite.`],
  [/^(.*?) 评分必须大于 0。$/u,(_,name)=>`${name} score must be greater than 0.`],
  [/^(.*?) 只能设置一条准入规则。$/u,(_,name)=>`${name} can have only one eligibility rule.`],
  [/^(.*?) 的比较方式应为“不低于”或“不高于”。$/u,(_,name)=>`${name} must use “at least” or “at most”.`],
  [/^(.*?) 的阈值必须是大于或等于零的有限数值。$/u,(_,name)=>`${name} must have a finite threshold greater than or equal to zero.`],
  [/^(.*?) 的资质核验状态无效。$/u,(_,name)=>`${name} has an invalid qualification verification status.`],
  [new RegExp(`^(.*?)为 (${NUMBER})，未满足(不低于|不高于) (${NUMBER})。$`,'u'),(_,name,value,op,threshold)=>`${name} is ${value}; it does not meet the ${op==='不低于'?'minimum':'maximum'} of ${threshold}.`],
  [/^服务器请求失败（(\d{3})）。$/u,(_,status)=>`The server request failed (${status}).`],
  [/^项目未确认保存：([\s\S]*)$/u,(_,detail)=>`The project save is unconfirmed: ${englishSystemText(detail)}`],
  [/^本地项目「([\s\S]*)」无法读取，请先检查备份。$/u,(_,title)=>`Local project “${title}” cannot be read. Check its backup first.`],
  [/^本地项目「([\s\S]*)」超过单次迁移的 6 MB 限制，请先导出备份并整理该项目。$/u,(_,title)=>`Local project “${title}” exceeds the 6 MB migration limit. Export a backup and organize the project first.`],
  [/^已完成 (\d+)\/(\d+) 个项目。(其余项目可使用相同确认重试。 )?([\s\S]*)$/u,(_,done,total,retry,detail)=>`${done}/${total} projects completed.${retry?' Retry the remaining projects using the same confirmation.':''} ${englishSystemText(detail)}`],
  [/^评估 V(\d+)$/u,(_,version)=>`Assessment V${version}`],
  [/^(\d+) 家供应商 · (\d+) 项指标$/u,(_,suppliers,criteria)=>`${suppliers} suppliers · ${criteria} criteria`],
  [new RegExp(`^覆盖 (${NUMBER})% · 自动容差$`,'u'),(_,p)=>`Coverage ${p}% · automatic tolerance`],
  [new RegExp(`^覆盖 (${NUMBER})% · 容差 (${NUMBER})$`,'u'),(_,p,delta)=>`Coverage ${p}% · tolerance ${delta}`],
];

export function englishSystemText(value){
  if(typeof value!=='string')return value;
  if(EXACT.has(value))return EXACT.get(value);
  if(value.endsWith('无效。')){
    const field=value.slice(0,-3);
    if(INVALID_FIELDS.has(field))return `${INVALID_FIELDS.get(field)} is invalid.`;
  }
  for(const [pattern,render]of PATTERNS){const match=pattern.exec(value);if(match)return render(...match);}
  return value;
}
